from pathlib import Path
import json,numpy as np
from scipy.spatial.transform import Rotation
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
O=Path(__file__).parent;fig,axes=plt.subplots(2,3,figsize=(14,7))
for col,(day,start) in enumerate([('2026-01-03',447),('2026-01-03',450),('2026-02-15',3387)]):
 a=np.load(O/f'{day}-{start}-reanchored-added-body.npz');t=a['t']-a['t'][0];truth=a['truth'];pred=Rotation.from_quat(a['states'][:,3:7]).as_euler('xyz')
 for row,k in enumerate([0,2]):
  ref=truth[:,k].copy();out=pred[:,k].copy()
  if k==2:ref=np.unwrap(ref)-ref[0];out=np.unwrap(out)-out[0]
  axes[row,col].plot(t,np.rad2deg(ref),color='#173d57',label='Flight',lw=2);axes[row,col].plot(t,np.rad2deg(out),color='#c16631',label='Added-inertia fit',lw=2);axes[row,col].grid(alpha=.2);axes[row,col].set_xlabel('Forecast time (s)')
 axes[0,col].set_title(('Hood River' if day.endswith('03') else 'Trout Lake')+f' | {start} s')
axes[0,0].set_ylabel('Payload bank (deg)');axes[1,0].set_ylabel('Payload heading change (deg)');axes[0,0].legend();fig.suptitle('Mechanics passed; the first flight fit did not',fontsize=16);fig.tight_layout(rect=(0,0,1,.95));fig.savefig(O/'iteration-added-body-flight.png',dpi=150);plt.close(fig)
p=O/'physics-development.html';s=p.read_text(encoding='utf-8');section='''<section id="added-inertia-fit"><h2>First added-inertia flight fit: rejected</h2><figure><img src="iteration-added-body-flight.png" alt="Measured bank and heading compared with the rejected added-inertia flight fit"><figcaption>Observable payload state is reset at the start of each three-second forecast; hidden relative canopy state is inferred from the preceding two seconds. These plots show the first fit with provisional added-inertia geometry. They do not show an accepted model.</figcaption></figure><p>Training loss falls, but reanchored bank errors range from 11 to 42 degrees RMS across the six development maneuvers, with large heading and velocity errors. The 450-second Hood River replay changes by up to 10.5 degrees in attitude and 0.88 m/s in a velocity component when the integration step is halved from 10 to 5 ms. The other cases mostly converge numerically and still miss the flight. Thus both numerical stiffness in an extreme replay and model/identification error need attention. Fitted roll damping reaches its search bound; the fitted parameter set is rejected.</p><figure><img src="iteration-rate-initialization.png" alt="Filtered gyro rates compared with rates derived from attitude"><figcaption>Initial-rate diagnostic over ten-second high-bank sequences. Both curves in this diagnostic use centered smoothing, so neither is a strictly causal estimator. These plots measure disagreement, not which signal is correct.</figcaption></figure><p>This audit also found that the earlier development fits used centered filtering at the initialization boundary. That introduces a small look-ahead and must be removed from final forecast validation. A separate trial uses a quadratic fit to only the previous 0.4 seconds of attitude, converted to body rates with full Euler kinematics. It does not rescue the rejected added-inertia fit. Final validation must use a past-only estimator and report initialization uncertainty.</p><p>The <a href="https://hobbyking.com/h-king-pnf-high-performance-paramotor-v2-w-led-light-bar-2400mm-94.html">manufacturer describes the V2 as a single-skin 2400 mm canopy</a>. The current effective area, projected span, suspension geometry and apparent-inertia centers are still provisional. A thick ram-air-wing geometry must not be silently assigned to it. Next identification needs geometry-consistent priors, longer response windows and converged integration rather than accepting low training loss.</p><p>Results: <code>added-body-fit.json</code>, <code>added-body-reanchored-validation.json</code>, <code>added-body-causal-validation.json</code>. The verified spatial-inertia solver is retained for further work; the fitted coefficients are not promoted to the production simulator.</p></section>'''
if 'id="added-inertia-fit"' not in s:p.write_text(s.replace('</html>',section+'</html>'),encoding='utf-8')
